def transform(grid):
    from collections import Counter, deque

    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    outline = min(counts, key=counts.get)
    out = [row[:] for row in grid]
    seen = set()

    # Treat diagonal outline contacts as closed boundaries as well.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == outline or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            region = []
            reaches_edge = False
            while q:
                y, x = q.popleft()
                region.append((y, x))
                if y == 0 or x == 0 or y == h - 1 or x == w - 1:
                    reaches_edge = True
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        if dy == dx == 0:
                            continue
                        ny, nx = y + dy, x + dx
                        if (0 <= ny < h and 0 <= nx < w and
                                grid[ny][nx] != outline and (ny, nx) not in seen):
                            seen.add((ny, nx))
                            q.append((ny, nx))
            if not reaches_edge:
                for y, x in region:
                    out[y][x] = 4
    return out
